def oracle(m):
 k=m['kind']
 if k=='date':
  fields={'YYYY':str(m['year']).rjust(4,'0'),'MM':str(m['month']).rjust(2,'0'),'DD':str(m['day']).rjust(2,'0')};keys=['YYYY','MM','DD'] if m['format']=='YYYYMMDD' else ['DD','MM','YYYY'];s=''.join(fields[a] for a in keys);zeros=[i+1 for i,c in enumerate(s) if c=='0'];assert s==m['expected'] and zeros==m['zero_positions'] and len(s)==8
  return dict(fields=fields,order=keys,string=s,length=len(s),zero_positions=zeros,zero_count=len(zeros),integer_conversion_would_drop_leading_zero=s.startswith('0'))
 if k.startswith('compound'):
  rate=F(m['rate'],) /100;factor=1+rate
  if k=='compound_forward':
   p=F(m['principal']);periods=[];n=p
   for y in range(m['years']):interest=n*rate;periods.append([str(n),str(interest),str(n+interest)]);n+=interest
   simple=p+m['years']*p*rate;assert n==F(m['expected_final']) and simple==F(m['expected_simple']);dd=D(m['principal'])*(1+D(m['rate'])/100)**m['years'];assert F(dd)==n
   return dict(periods=periods,compound=str(n),simple=str(simple),difference=str(n-simple),fraction_decimal_agree=True)
  final=F(m['final']);p=final/(factor**m['years']);assert p==F(m['expected_principal']);n=p;interests=[]
  for _ in range(m['years']):i=n*rate;interests.append(i);n+=i
  assert interests==[F(x) for x in m['expected_interests']] and n==final;return dict(principal=str(p),interests=[str(x) for x in interests],final=str(n))
 if k.startswith('pair'):
  pool=[('R'+str(i),'red') for i in range(m['red'])]+[('B'+str(i),'blue') for i in range(m['blue'])]
  if k=='pair':
   trials=list(combinations(pool,m['draws']));counts=[Counter(c for _,c in t) for t in trials];anypair=all(max(c.values())>=2 for c in counts);redpair=all(c['red']>=2 for c in counts);assert anypair==m['expected_any_pair'] and redpair==m['expected_red_pair'];return dict(distinct_object_subsets=len(trials),possible_color_counts=sorted({(c['red'],c['blue']) for c in counts}),guaranteed_any_pair=anypair,guaranteed_red_pair=redpair)
  checks={n:all(sum(color=='blue' for _,color in t)>=m['target_blue'] for t in combinations(pool,n)) for n in range(1,len(pool)+1)};minimum=min(n for n,yes in checks.items() if yes);assert minimum==m['expected_min'];return dict(all_sample_size_guarantees=checks,minimum=minimum)
 if k=='clock_forward':
  elapsed=F(m['true_end']-m['reset_minutes']);display=m['reset_minutes']+elapsed*F(m['display_minutes_per_real_hour'],60);assert display==m['expected_display'];return dict(real_elapsed_minutes=str(elapsed),display_time_minutes=str(display),signed_display_minus_true_minutes=str(display-m['true_end']))
 if k=='clock_inverse':
  delta=F(m['display_end']-m['reset_minutes']);elapsed=delta*F(60,m['display_minutes_per_real_hour']);true=m['reset_minutes']+elapsed;assert true==m['expected_true'];assert elapsed*F(m['display_minutes_per_real_hour'],60)==delta;return dict(display_elapsed_minutes=str(delta),real_elapsed_minutes=str(elapsed),true_time_minutes=str(true),display_error=str(m['display_end']-true))
 if k.startswith('train'):
  if k=='train_forward':L=m['train'];T=F(m['bridge']+L,m['speed']);assert T==m['expected_time'] and m['bridge']+L==m['expected_distance']
  else:T=F(m['time']);L=T*m['speed']-m['bridge'];assert L==m['expected_train'] and L>0
  front_start=F(0);tail_start=-L;front_end=front_start+m['speed']*T;tail_end=tail_start+m['speed']*T;assert tail_end==m['bridge'];return dict(train_length=str(L),time=str(T),front_start=str(front_start),tail_start=str(tail_start),front_end=str(front_end),tail_end=str(tail_end),tail_clears_end=True)
 if k.startswith('piecewise'):
  times=[F(d,v) for d,v in m['segments']];distance=sum(d for d,v in m['segments']);moving=sum(times)
  if k=='piecewise_compare':
   other=F(m['other_distance'],m['other_speed']);avg=F(distance)/moving;assert moving==F(m['expected_time']) and other==F(m['expected_other_time']) and avg==F(m['expected_average']);return dict(segment_times=[str(t) for t in times],A_time=str(moving),B_time=str(other),A_average=str(avg),arrival_comparison='same' if moving==other else 'A_first' if moving<other else 'B_first')
  total=moving+F(m['rest_minutes'],60);avg=F(distance)/total;assert moving==F(m['expected_moving']) and total==F(m['expected_total']) and avg==F(m['expected_average']);return dict(segment_times=[str(t) for t in times],moving=str(moving),total=str(total),distance=distance,total_average=str(avg),moving_average=str(F(distance)/moving))
 raise ValueError(k)

